```java
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class CarCountByColor {
    public static Map<String, Integer> getMostPopularCarColor(List<Car> cars) {
        return cars.stream()
                .collect(Collectors.groupingBy(Car::getColor, Collectors.counting()))
                .entries()
                .stream()
                .max(Map.Entry.comparingByValue())
                .map(Map.Entry::getKey)
                .orElse(null) // return null if no cars are present
                .map(color -> new Pair<>(color, cars.stream()
                        .filter(car -> car.getColor().equals(color))
                        .count()))
                .orElse(null); // return null if no most popular color is found
    }

    // Helper class to store color and count
    private static class Pair<K, V> {
        private final K key;
        private final V value;

        private Pair(K key, V value) {
            this.key = key;
            this.value = value;
        }

        public K getKey() {
            return key;
        }

        public V getValue() {
            return value;
        }
    }
}
```

In this example, the `getMostPopularCarColor` method first groups cars by their color using the `groupingBy` collector, then finds the group with the maximum number of cars using the `max` collector, and returns the color and count of the most popular car. If no cars are present in the list, the method returns `null`.

